#include "LearningIPC.h"
#include "CaptureIPC.h"
#include <atomic>
#include <cmath>
#include <algorithm>
namespace private_input::activity {
LearningReader::~LearningReader(){stop();}
void LearningReader::stop(){{std::lock_guard<std::mutex>guard(lock);stopping=true;}wake.notify_one();if(worker.joinable())worker.join();}
void LearningReader::start(std::filesystem::path model,std::function<void()>prepare,std::function<void()>settings){if(!worker.joinable())try{stopping=false;publicPath=std::move(model);preparePublic=std::move(prepare);refreshSettings=std::move(settings);worker=std::thread([this]{try{run();}catch(...) {}});}catch(...) {}}
void LearningReader::run(){if(refreshSettings)refreshSettings();if(preparePublic)preparePublic();if(!publicPath.empty()){auto model=std::make_shared<private_input::PublicContextModel>();if(model->load(publicPath)){std::shared_ptr<const private_input::PublicContextModel>frozen=model;std::atomic_store(&publicModel,std::move(frozen));}}LONG previous=-1;uint64_t lastSettings=GetTickCount64();HANDLE opened=nullptr;const LearningMapping*data=nullptr;for(;;){{std::unique_lock<std::mutex>guard(lock);if(wake.wait_for(guard,std::chrono::milliseconds(250),[&]{return stopping;}))break;}if(refreshSettings&&GetTickCount64()-lastSettings>=1000){lastSettings=GetTickCount64();refreshSettings();}if(!data){opened=OpenFileMappingW(FILE_MAP_READ,FALSE,learningName().c_str());if(opened)data=static_cast<const LearningMapping*>(MapViewOfFile(opened,FILE_MAP_READ,0,0,sizeof(LearningMapping)));if(!data){if(opened)CloseHandle(opened);opened=nullptr;continue;}}auto revision=data->revision;MemoryBarrier();bool stale=GetTickCount64()<data->updatedTick||GetTickCount64()-data->updatedTick>90000;if((revision==previous&&!stale)||(revision&1))continue;auto next=std::make_shared<LearningSnapshot>();if(!stale&&data->version==1&&data->enabled&&data->count<=LearningRowLimit){for(uint32_t i=0;i<data->count;++i){LearningRow row;memcpy(&row,&data->rows[i],sizeof(row));if(!memchr(row.reading,0,sizeof(row.reading))||!memchr(row.text,0,sizeof(row.text))||row.frequency>1000000000||row.pinned>1||row.kind>2||!std::isfinite(row.recent)||row.recent< -1||row.recent>1)continue;if(row.kind){next->personal.push_back(row);next->explicitKeys.insert(canonicalLearningReading(row.reading)+char(31)+row.text);}else{auto reading=canonicalLearningReading(row.reading);next->scores[reading+char(31)+row.text]={row.frequency,row.pinned!=0,row.recent};{auto compact=reading;compact.erase(std::remove(compact.begin(),compact.end(),' '),compact.end());next->spelling[compact].push_back({reading,row.text});}}}}MemoryBarrier();if(data->revision!=revision||(revision&1))continue;previous=revision;std::shared_ptr<const LearningSnapshot>frozen=next;std::atomic_store(&snapshot,std::move(frozen));}if(data)UnmapViewOfFile(data);if(opened)CloseHandle(opened);}
}
